<?php
/**
 * Google Authenticator (TOTP, RFC 6238) helpers.
 * Codes are generated by the user's authenticator app; the server only stores
 * the shared secret and verifies 6-digit codes (SHA1, 30-second period).
 */

function base32_encode(string $data): string
{
    $alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    $binary = '';
    foreach (str_split($data) as $char) {
        $binary .= str_pad(decbin(ord($char)), 8, '0', STR_PAD_LEFT);
    }
    $out = '';
    foreach (str_split($binary, 5) as $chunk) {
        $out .= $alphabet[bindec(str_pad($chunk, 5, '0', STR_PAD_RIGHT))];
    }
    return $out;
}

function base32_decode(string $encoded): string
{
    // Tolerate manual-entry formatting (spaces, dashes, padding), but reject
    // any character outside the Base32 alphabet instead of silently dropping it.
    $encoded = strtoupper(preg_replace('/[\s\-=]/', '', $encoded));
    if ($encoded === '' || preg_match('/[^A-Z2-7]/', $encoded)) {
        return '';
    }
    $binary = '';
    foreach (str_split($encoded) as $char) {
        $pos = strpos('ABCDEFGHIJKLMNOPQRSTUVWXYZ234567', $char);
        if ($pos === false) {
            return '';
        }
        $binary .= str_pad(decbin($pos), 5, '0', STR_PAD_LEFT);
    }
    $out = '';
    foreach (str_split($binary, 8) as $byte) {
        if (strlen($byte) === 8) {
            $out .= chr(bindec($byte));
        }
    }
    return $out;
}

/** 160-bit random secret, Base32-encoded (32 characters) for authenticator apps. */
function totp_generate_secret(): string
{
    return base32_encode(random_bytes(20));
}

/** Compute the 6-digit TOTP code for a given time counter (RFC 6238 / RFC 4226). */
function totp_code_at(string $secret, int $counter): string
{
    $key = base32_decode($secret);
    if ($key === '') {
        return '';
    }
    $time = pack('N*', 0) . pack('N*', $counter);
    $hash = hash_hmac('sha1', $time, $key, true);
    $offset = ord($hash[19]) & 0x0F;
    $value = ((ord($hash[$offset]) & 0x7F) << 24)
        | ((ord($hash[$offset + 1]) & 0xFF) << 16)
        | ((ord($hash[$offset + 2]) & 0xFF) << 8)
        | (ord($hash[$offset + 3]) & 0xFF);
    return str_pad((string) ($value % 1000000), 6, '0', STR_PAD_LEFT);
}

function totp_current_code(string $secret): string
{
    return totp_code_at($secret, intdiv(time(), 30));
}

/** Verify a user-entered code, allowing ±1 time step (30s) of clock drift. */
function totp_verify(string $secret, string $code, int $window = 1): bool
{
    if (!preg_match('/^\d{6}$/', $code) || $secret === '') {
        return false;
    }
    $slice = intdiv(time(), 30);
    for ($i = -$window; $i <= $window; $i++) {
        if (hash_equals(totp_code_at($secret, $slice + $i), $code)) {
            return true;
        }
    }
    return false;
}

/** otpauth:// URI rendered as a QR code for Google Authenticator enrollment. */
function totp_uri(string $secret, string $accountName, string $issuer = 'Surf to Sawa'): string
{
    $label = rawurlencode($issuer) . ':' . rawurlencode($accountName);
    return 'otpauth://totp/' . $label
        . '?secret=' . $secret
        . '&issuer=' . rawurlencode($issuer)
        . '&algorithm=SHA1&digits=6&period=30';
}

/** Format a Base32 secret in groups of 4 for manual entry. */
function totp_display_secret(string $secret): string
{
    return trim(chunk_split($secret, 4, ' '));
}

/**
 * Brute-force protection: 5 failed codes per 5-minute window locks the
 * user+purpose pair for 5 minutes. Returns a lock message, or null if allowed.
 */
function totp_attempt_check(mysqli $conn, int $userId, string $purpose): ?string
{
    $stmt = $conn->prepare('SELECT attempts, first_attempt_at, locked_until FROM totp_attempts WHERE user_id = ? AND purpose = ?');
    $stmt->bind_param('is', $userId, $purpose);
    $stmt->execute();
    $row = $stmt->get_result()->fetch_assoc();
    if (!$row) {
        return null;
    }
    if ($row['locked_until'] !== null && strtotime($row['locked_until']) > time()) {
        $minutes = (int) ceil((strtotime($row['locked_until']) - time()) / 60);
        return 'Too many incorrect codes. Try again in ' . max(1, $minutes) . ' minute(s).';
    }
    if (strtotime($row['first_attempt_at']) <= time() - 300) {
        $clear = $conn->prepare('DELETE FROM totp_attempts WHERE user_id = ? AND purpose = ?');
        $clear->bind_param('is', $userId, $purpose);
        $clear->execute();
    }
    return null;
}

/** Record a failed code; lock after 5 failures inside the window. */
function totp_attempt_record_failure(mysqli $conn, int $userId, string $purpose): void
{
    $stmt = $conn->prepare('SELECT attempts, first_attempt_at FROM totp_attempts WHERE user_id = ? AND purpose = ?');
    $stmt->bind_param('is', $userId, $purpose);
    $stmt->execute();
    $row = $stmt->get_result()->fetch_assoc();
    $fresh = !$row || strtotime($row['first_attempt_at']) <= time() - 300;
    $attempts = $fresh ? 1 : ((int) $row['attempts'] + 1);
    $lockedUntil = $attempts >= 5 ? date('Y-m-d H:i:s', time() + 300) : null;
    $firstAt = $fresh ? date('Y-m-d H:i:s') : $row['first_attempt_at'];
    $upsert = $conn->prepare('INSERT INTO totp_attempts (user_id, purpose, attempts, first_attempt_at, locked_until) VALUES (?, ?, ?, ?, ?)
        ON DUPLICATE KEY UPDATE attempts = VALUES(attempts), first_attempt_at = VALUES(first_attempt_at), locked_until = VALUES(locked_until)');
    $upsert->bind_param('isiss', $userId, $purpose, $attempts, $firstAt, $lockedUntil);
    $upsert->execute();
}

/** Clear the failure counter after a successful verification. */
function totp_attempt_clear(mysqli $conn, int $userId, string $purpose): void
{
    $stmt = $conn->prepare('DELETE FROM totp_attempts WHERE user_id = ? AND purpose = ?');
    $stmt->bind_param('is', $userId, $purpose);
    $stmt->execute();
}
?>
